const headers = $json.headers || {};
const body = $json.body?.body || $json.body || $json;
const token = headers['x-synapse-webhook-token'] || headers['X-Synapse-Webhook-Token'];
const expected = $env.SCRAPER_ERROR_WEBHOOK_TOKEN || '';

if (expected && token !== expected) {
  return [{ json: { ok: false, status: 401, message: 'Token de webhook inválido' } }];
}

const severity = (body.severity || 'warning').toLowerCase();
const isCritical = severity === 'critical' || severity === 'critico' || severity === '1';
const gradeLabel = isCritical ? 'CRÍTICO (1er Grado)' : 'ADVERTENCIA (2do Grado)';
const emoji = isCritical ? '🚨' : '⚠️';

const service = body.service_name || body.service || 'MDM_Farmaceutico_Scraper';
const origin = body.origin_entity || 'Servidor Debian Webservices';
const originIp = body.origin_ip ? ` (IP: ${body.origin_ip})` : '';
const destination = body.destination_entity || 'Servicio externo';
const diagnosis = body.diagnosis || body.message || 'Error reportado por el scraper sin detalle.';
const causes = body.probable_causes || body.causes || 'Revisar logs del scraper y conectividad del servicio destino.';
const nativeLog = body.native_log || body.details || JSON.stringify(body.context || {});

const structured = [
  `${emoji} ${gradeLabel}: ${body.title || diagnosis.split('.')[0]}`,
  `🖥️ Entidad Origen: ${origin}${originIp}`,
  `🎯 Entidad Destino: ${destination}`,
  `🔌 Servicio Afectado: ${service}`,
  '',
  `📝 Diagnóstico: ${diagnosis}`,
  `🔍 Causas Probables: ${causes}`,
  `🛠️ Log Nativo (scraper): ${nativeLog}`
].join('\n');

const workflowId = body.workflow_id || 'AAnxxGYtgg5sD0o8';
const workflowName = body.workflow_name || '[PROD] Orquestador Clasificador (Ventanas)';
const executionId = body.execution_id || `scraper-${Date.now()}`;

return [{
  json: {
    ok: true,
    status: 200,
    message: 'Alerta encolada',
    error_notification_payload: {
      execution: {
        error: { message: structured },
        id: executionId,
        url: `https://n8n.farmaciaamericana.es/workflow/${workflowId}/executions/${executionId}`
      },
      workflow: {
        name: workflowName,
        id: workflowId
      }
    }
  }
}];
